<script setup>
import PortalLayout from '@/Layouts/PortalLayout.vue'; import { Head, Link, router } from '@inertiajs/vue3'; const props=defineProps({product:{type:Object,required:true}}); const remove=()=>{if(window.confirm(`Delete ${props.product.name}? This cannot be undone.`))router.delete(route('admin.products.destroy',props.product.slug));};
</script>
<template><Head :title="product.name"/><PortalLayout area="Administration"><template #navigation><Link :href="route('admin.dashboard')" class="block rounded-lg px-3 py-2 text-slate-600">Overview</Link><Link :href="route('admin.products.index')" class="block rounded-lg bg-cyan-50 px-3 py-2 font-medium text-cyan-800">Products</Link></template><div v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</div><div class="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between"><div><h1 class="text-3xl font-bold text-slate-900">{{ product.name }}</h1><p class="mt-2 text-slate-600">{{ product.short_description }}</p><p class="mt-1 text-sm text-slate-500">{{ product.code }} · {{ product.category }} · {{ product.status }}</p></div><div class="flex flex-wrap gap-2"><Link :href="route('admin.products.plans.index',product.slug)" class="rounded-xl border border-cyan-200 px-5 py-3 font-bold text-cyan-800">Plans</Link><Link :href="route('admin.products.edit',product.slug)" class="form-button">Edit</Link><button class="rounded-xl border border-red-200 px-5 py-3 font-bold text-red-700" @click="remove">Delete</button></div></div><p class="mt-8 whitespace-pre-line text-slate-600">{{ product.description }}</p><div class="mt-8 grid gap-8 md:grid-cols-3"><section><h2 class="font-bold">Features ({{ product.feature_records?.length||0 }})</h2><ul class="mt-3 space-y-2 text-sm text-slate-600"><li v-for="item in product.feature_records" :key="item.uuid">{{ item.name }}</li></ul></section><section><h2 class="font-bold">Media ({{ product.media?.length||0 }})</h2><ul class="mt-3 space-y-2 text-sm text-slate-600"><li v-for="item in product.media" :key="item.uuid">{{ item.title||item.type }}</li></ul></section><section><h2 class="font-bold">Links ({{ product.links?.length||0 }})</h2><ul class="mt-3 space-y-2 text-sm"><li v-for="item in product.links" :key="item.uuid"><a :href="item.url" target="_blank" rel="noopener noreferrer" class="text-cyan-700">{{ item.label }}</a></li></ul></section></div></div></PortalLayout></template>
